import subprocess, json

for test_note in ['===', 'OFF', 97]:
    cmd = ['ft2', 'call', 'pattern_set_cell', json.dumps({
        'pattern': 0,
        'row': 1,
        'channel': 0,
        'note': test_note
    })]
    res = subprocess.run(cmd, capture_output=True, text=True)
    cmd2 = ['ft2', 'call', 'pattern_get_cell', json.dumps({
