{"command": "python3 -c "
import subprocess, json, wave, numpy as np

# Test 3 rows with 3 different volumes
subprocess.run(['ft2', 'call', 'pattern_clear', json.dumps({'pattern': 0})])

# Let's test vol 64
subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 0, 'channel': 0, 'note': 'C-4', 'instrument': 1, 'volume': 64
})])
# Cut it at row 3
subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 3, 'channel': 0, 'note': 97
})])

# Test vol 32 at row 4
subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 4, 'channel': 0, 'note': 'C-4', 'instrument': 1, 'volume': 32
})])
# Cut at row 7
subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 7, 'channel': 0, 'note': 97
})])

# Test vol 0 (no vol specified) at row 8
subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 8, 'channel': 0, 'note': 'C-4', 'instrument': 1
})])
# Cut at row 11
subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 11, 'channel': 0, 'note': 97
})])

# Test effect C (set volume to 64: effect 12, param 64) at row 12
subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 12, 'channel': 0, 'note': 'C-4', 'instrument': 1, 'effect': 12, 'effect_param': 64
})])
# Cut at row 15
subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 15, 'channel': 0, 'note': 97
})])

subprocess.run(['ft2', 'call', 'module_render', json.dumps({
    'path': '/workspace/test_vol_render.wav',
    'rate': 44100,
    'bits': 16,
    'start': 0,
    'stop': 0
})])

with wave.open('/workspace/test_vol_render.wav', 'rb') as w:
    frames = w.getnframes()
    data = np.frombuffer(w.readframes(frames), dtype=np.int16).reshape(-1, 2)
    # Row duration at bpm 125, speed 6:
    row_len = int(44100 * (2.5 * 6 / 125))
    print(f'Row len in samples: {row_len}')

    # Check max amp in row 0..2 (vol 64)
    v64 = np.max(np.abs(data[0:row_len*2, 0]))
    # Check max amp in row 4..6 (vol 32)
    v32 = np.max(np.abs(data[row_len*4:row_len*6, 0]))
    # Check max amp in row 8..10 (default vol)
    vdef = np.max(np.abs(data[row_len*8:row_len*10, 0]))
    # Check max amp in row 12..14 (effect C 64)
    vc64 = np.max(np.abs(data[row_len*12:row_len*14, 0]))
    print(f'Max amplitudes: vol=64 -> {v64}, vol=32 -> {v32}, default -> {vdef}, fx C 64 -> {vc64}')
""}

