for name in ['A-4', 'A#4', 'Bb-4', 'Bb4', 'C-4', 'C#4', 'Db4', 'D-2', 'F-2', 'A-2', 'A#2']:
    res = subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
        'pattern': 0, 'row': 0, 'channel': 0, 'note': name, 'instrument': 1
    })], capture_output=True, text=True)
    d = json.loads(res.stdout)
    err = d.get('isError', False)
    # also read cell to see what note number it got
    c = json.loads(subprocess.run(['ft2', 'call', 'pattern_get_cell', json.dumps({
        'pattern': 0, 'row': 0, 'channel': 0
    })], capture_output=True, text=True).stdout)
    c_text = json.loads(c['content'][0]['text'])
    print(f'{name}: isError={err}, note_num={c_text.get(\"note\")}, note_name={c_text.get(\"note_name\")}')
""}

