{"command": "python3 -c "
import subprocess, json

looping_insts = {7, 8, 9, 12} # Sub Bass, Pulse Lead, Supersaw, Lush Pad

for p in range(7):
    # Track state of each channel
    chan_playing = {ch: None for ch in range(10)}
    for r in range(64):
        for ch in range(10):
            res = subprocess.run(['ft2', 'call', 'pattern_get_cell', json.dumps({
                'pattern': p, 'row': r, 'channel': ch
            })], capture_output=True, text=True)
            cell = json.loads(json.loads(res.stdout)['content'][0]['text'])
            note = cell['note']
            inst = cell['instrument']

            if note == 97: # key off
                chan_playing[ch] = None
            elif note > 0:
                if inst in looping_insts:
                    chan_playing[ch] = (inst, r)
                elif inst > 0:
                    chan_playing[ch] = None # one shot
    # At end of pattern, check which channels are still playing a looping instrument
    for ch, val in chan_playing.items():
        if val is not None:
            print(f'Pattern {p}, Ch {ch}: looping inst {val[0]} triggered at row {val[1]} is still playing at row 63!')
""}

